<script setup lang="ts">
import { Head } from '@inertiajs/vue3';
import { onMounted, ref } from 'vue';
import AppShell from '../components/AppShell.vue';
import { api, type CurrentUser } from '../lib/api';
const user = ref<CurrentUser | null>(null); const settings = ref<Record<string, any>[]>([]); const loading = ref(true); const saving = ref(false); const message = ref(''); const error = ref('');
onMounted(async () => { try { user.value = (await api.me()).data; settings.value = (await api.settings.list()).data as Record<string, any>[]; } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to load settings.'; } finally { loading.value = false; } });
const save = async () => { saving.value = true; try { await api.settings.update(settings.value); message.value = 'Settings saved successfully.'; } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to save settings.'; } finally { saving.value = false; } };
</script>
<template><Head title="Settings" /><AppShell title="Settings" :user="user"><section class="mx-auto max-w-5xl space-y-6 p-5 sm:p-8"><div class="flex items-end justify-between"><div><p class="text-xs font-bold uppercase tracking-widest text-teal-700">MANAGE</p><h1 class="mt-2 text-3xl font-bold text-slate-800">Business settings</h1><p class="mt-1 text-sm text-slate-500">Configure values used by billing and operations.</p></div><button class="rounded-lg bg-teal-700 px-4 py-2.5 text-sm font-semibold text-white" :disabled="saving" @click="save">{{ saving ? 'Saving...' : 'Save settings' }}</button></div><p v-if="message" class="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-700">{{ message }}</p><p v-if="error" class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{ error }}</p><div class="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><p v-if="loading" class="text-sm text-slate-400">Loading settings...</p><div v-else-if="settings.length" class="grid gap-5 sm:grid-cols-2"><label v-for="setting in settings" :key="setting.key" class="text-xs font-semibold text-slate-600">{{ setting.key }}<input v-model="setting.value" class="mt-2 w-full rounded-lg border border-slate-200 px-3 py-2.5 text-sm outline-none focus:border-teal-600" :type="setting.type === 'number' ? 'number' : 'text'" /></label></div><p v-else class="text-sm text-slate-400">No settings have been configured yet.</p></div></section></AppShell></template>
